<style>
.hag-release{max-width:1140px;margin:0 auto;padding:48px 24px;color:inherit}.hag-release-card{border:1px solid rgba(148,163,184,.28);border-radius:28px;padding:clamp(24px,5vw,56px);background:linear-gradient(130deg,#09131f,#143449);color:#f8fafc;box-shadow:0 24px 70px rgba(0,0,0,.13)}.hag-release-card h1,.hag-release-card h2{font-size:clamp(27px,4vw,42px);line-height:1.3;font-weight:800;margin:16px 0}.hag-release-card p{max-width:660px;line-height:1.9;color:#d4e1eb}.hag-release-wordmark{font-size:30px;font-weight:900;letter-spacing:4px;color:#d9b879}.hag-release-action{display:inline-flex;align-items:center;justify-content:center;min-height:48px;padding:13px 23px;background:#d9b879;color:#09131f!important;border-radius:14px;font-weight:800;text-decoration:none;margin-top:16px}.hag-release-links{display:flex;flex-wrap:wrap;gap:20px;margin-top:24px}.hag-release-links a{text-decoration:underline}.hag-release-guide{margin:28px 0;line-height:1.9}.hag-release-guide ol{list-style:decimal;padding-inline-start:24px}.hag-release-guide li{margin:12px 0}.hag-map-filter{display:flex;flex-wrap:wrap;gap:10px;margin:20px 0}.hag-map-filter button{border:1px solid #64748b;padding:10px 16px;border-radius:24px;background:#102b3e;color:#e2e8f0}.hag-map-filter button[aria-pressed=true]{background:#d9b879;color:#09131f;border-color:#d9b879}.hag-map-filter label{padding:10px}.hag-map-list{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:16px;margin-top:24px;max-height:560px;overflow:auto}.hag-map-item{padding:18px;border:1px solid rgba(148,163,184,.35);border-radius:20px}.hag-map-item h3{font-weight:800}.hag-map-item p{margin:8px 0}.hag-map-item img{width:100%;height:140px;object-fit:cover;border-radius:12px;margin-bottom:12px}.hag-map-item a{text-decoration:underline}.hag-map-popup{min-width:200px;max-width:260px;line-height:1.6}.hag-map-popup img{width:100%;max-height:130px;object-fit:cover}.hag-map-popup a{font-weight:bold;text-decoration:underline}.hag-map-status{margin:12px 0;font-size:14px;line-height:1.8}.hag-map-marker{border-radius:50%;background:#09131f;color:#d9b879;border:2px solid #d9b879;width:36px;height:36px;display:grid;place-items:center;font-size:20px}.hag-map-marker[data-kind=yacht]{border-color:#67e8f9}.hag-map-marker[data-kind=boat]{border-color:#a7f3d0}.hag-experience-form{max-width:960px;margin:auto;padding:24px;line-height:1.8}.hag-experience-form section{border:1px solid #94a3b8;border-radius:20px;padding:24px;margin:20px 0}.hag-experience-form label{display:block;margin:14px 0 6px}.hag-experience-form input:not([type=checkbox]){width:100%;border:1px solid #64748b;border-radius:10px;padding:10px;color:#10243a;background:#fff}.hag-experience-form h1{font-size:28px;font-weight:800}.hag-experience-form h2{font-size:20px;font-weight:700}.hag-experience-form button{padding:12px 24px;border-radius:12px;background:#123449;color:#fff}.hag-experience-form .errors{color:#dc2626}.hag-experience-form a{text-decoration:underline}#location-picker{height:360px;border-radius:16px;margin-top:20px;z-index:1}.hag-map-item[hidden]{display:none}
